def has_cycle(self):
    """Return True if the graph has a directed cycle, False otherwise.

    A directed cycle is a path that starts and ends at the same node,
    following directed edges. An edge from a node to itself counts as a cycle.

    Returns:
        bool: True if there is a directed cycle, False otherwise
    """
    # Track visited nodes and nodes in current recursion stack
    visited = set()
    rec_stack = set()

    def dfs(node):
        # Mark current node as visited and add to recursion stack
        visited.add(node)
        rec_stack.add(node)

        # Check neighbors
        for neighbor, _ in self.neighbors(node):
            # If neighbor is not visited, recursively check it
            if neighbor not in visited:
                if dfs(neighbor):
                    return True
            # If neighbor is in recursion stack, we found a cycle
            elif neighbor in rec_stack:
                return True

        # Remove node from recursion stack
        rec_stack.remove(node)
        return False

    # Check all nodes for cycles
    for node in self.nodes():
        if node not in visited:
            if dfs(node):
                return True

    return False

get(key) {
  if (!this.map.has(key)) {
    return undefined;
  }

  // Get the value and move the key to the end (mark as most recently used)
  const value = this.map.get(key);
  this.map.delete(key);
  this.map.set(key, value);

  return value;
}

peek(key) {
  if (!this.map.has(key)) {
    return undefined;
  }

  // Get the value without moving the key (no LRU update)
  return this.map.get(key);
}
